//! End-to-end gate for the CX405 port: the Rust pipeline vs the
//! Python reference (camcorder-pipeline v1.2), run on the golden
//! input frames with drift neutralized and noise zeroed on BOTH
//! sides (fixtures generated by tools/gen_cx_ref.py logic — see
//! camcorder.rs module docs). Resize/blur kernel approximations
//! mean this is a tolerance gate, not byte equality: it exists to
//! catch stage-order, matrix, or LUT transcription errors, which
//! produce diffs an order of magnitude larger than kernel noise.

use openfuji_core::video::Camcorder;

const W: usize = 960;
const H: usize = 540;

fn load(name: &str) -> Vec<u8> {
    let path = format!(
        "{}/tests/fixtures/{}",
        env!("CARGO_MANIFEST_DIR"),
        name
    );
    std::fs::read(&path).unwrap_or_else(|e| panic!("read {path}: {e}"))
}

fn check(scene: &str) {
    let input = load(&format!("cx405_{scene}_in.rgb"));
    let reference = load(&format!("cx405_{scene}_ref.rgb"));
    assert_eq!(input.len(), W * H * 3);
    let mut cam = Camcorder::new(7);
    cam.drift_enabled = false;
    cam.noise_scale = 0.0;
    let out = cam.process_frame(&input, W, H, 0);
    assert_eq!(out.len(), reference.len());
    let mut diffs: Vec<u32> = out
        .iter()
        .zip(reference.iter())
        .map(|(a, b)| (*a as i32 - *b as i32).unsigned_abs())
        .collect();
    let mean = diffs.iter().sum::<u32>() as f64 / diffs.len() as f64;
    diffs.sort_unstable();
    let p99 = diffs[(diffs.len() as f64 * 0.99) as usize];
    let max = *diffs.last().unwrap();
    eprintln!("{scene}: mean|d|={mean:.3} p99={p99} max={max}");
    // Measured 2026-10-25 on the first verified port: park mean
    // 0.063 / rain mean 0.034, p99 = 1, max = 4. Bands hold ~4x
    // headroom for float/platform variance; a stage transcription
    // error lands an order of magnitude above them.
    assert!(
        mean <= 0.25,
        "{scene}: mean abs diff {mean:.3} exceeds 0.25 — a stage diverged from the Python reference"
    );
    assert!(p99 <= 3, "{scene}: p99 diff {p99} exceeds 3");
}

#[test]
fn cx405_matches_python_reference_park_day() {
    check("park_day");
}

#[test]
fn cx405_matches_python_reference_rain_night() {
    check("rain_night");
}
